#include "app.h"
#include "main.h"
#include "status.h"
#include "led.h"
#include "button.h"
#include "uart_port.h"
#include "i2c_port.h"
#include "spi_port.h"
#include "w25q128.h"
#include "sensor_service.h"
#include "shell.h"
#include "app_cmds.h"
#include "perf.h"
#include "scheduler.h"
#include "erase_job.h"

/* Generated by CubeMX */
extern UART_HandleTypeDef huart2;
extern I2C_HandleTypeDef hi2c1;
extern SPI_HandleTypeDef hspi1;

static const Led g_led = {
    .port = LED_GPIO_Port,
    .pin = LED_Pin,
    .active_high = true,
};

static Button g_btn_user = {
    .port = BTN_GPIO_Port,
    .pin = BTN_Pin,
    .active_low = true, /* Button to GND, internal pull-up */
    .debounce_ms = 30u,
};

/* Returns true once per press, so one press toggles the LED once */
static void task_button(void)
{
  if (button_update(&g_btn_user))
  {
    (void)led_toggle(&g_led);
  }
}

/* Task table, const: it stays in Flash. Order is the run order within a pass. */
static const sched_task_t s_tasks[] = {
    {"shell", 1u, shell_poll},
    {"sensor", 2u, sensor_service_poll},
    {"button", 5u, task_button},
    {"erase", 5u, erase_job_poll},
    {"scan", 0u, app_cmds_poll}, /* Every pass: keeps 'flash scan' fast */
};

void app_init(void)
{
  perf_init();

  /* Start with the LED off regardless of the CubeMX default level */
  if (led_init(&g_led) != STATUS_OK)
  {
    Error_Handler();
  }
  if (button_init(&g_btn_user) != STATUS_OK)
  {
    Error_Handler();
  }
  /* UART must be up before the shell prints its banner */
  if (uart_port_init(&huart2) != STATUS_OK)
  {
    Error_Handler();
  }
  if (i2c_port_init(&hi2c1) != STATUS_OK)
  {
    Error_Handler();
  }
  if (spi_port_init(&hspi1) != STATUS_OK)
  {
    Error_Handler();
  }
  /* The flash may be absent or miswired: report it in 'flash info'
   * instead of halting the whole system */
  (void)w25q_init(NULL);

  sensor_service_init();

  if (app_cmds_init(&g_led) != STATUS_OK)
  {
    Error_Handler();
  }
  if (sched_init(s_tasks, sizeof(s_tasks) / sizeof(s_tasks[0])) != STATUS_OK)
  {
    Error_Handler();
  }
}

void app_loop(void)
{
  perf_loop_tick(); /* Must stay the first call: it times one full pass */
  sched_run();
}